    final PrintStream out,
    final Object label,
    final Map<?, ?> map,
    final ArrayStack<Map<?, ?>> lineage,
    final boolean debug) {

    printIndent(out, lineage.size());

    if (map != null) {
        if (label != null) {
            out.print(label);
            out.print(" = ");
        }
